import re
def mathcomma(h):            # десятичная запятая внутри $…$ — {,}, чтобы KaTeX не ставил пробел
    return re.sub(r'\$[^$]+\$', lambda m: re.sub(r'(\d),(\d)', r'\1{,}\2', m.group(0)), h)
def pack(tasks, tid_prefix, parts):
    blocks = []
    for title, rng, extra in parts:
        ts = []
        for n in rng:
            t = dict(tasks[n - 1]); sol = t.pop('sol'); t = {'n': n, **t, 'bank_id': None, 'tid': f"{tid_prefix}-{n:02d}"}
            SOL.setdefault(tid_prefix, {})[str(n)] = {'answer': sol[0], 'html': mathcomma(sol[1])}
            ts.append(t)
        blocks.append({'title': title, **extra, 'tasks': ts})
    return blocks
